1071	fn re_str(v: &V) -> Result<(Rc<Vec<char>>, V), E> {
1072	    match v {
1073	        // The last string searched keeps its characters: a loop that tries many patterns on one text (#195)
1074	        // converts it once. Holding the string keeps its address from being reused.
1075	        V::Str(x) => {
1076	            thread_local! { static LAST: RefCell<Option<(Rc<S>, Rc<Vec<char>>)>> = RefCell::new(None); }
1077	            if let Some(c) = LAST.with(|l| l.borrow().as_ref().filter(|(k, _)| Rc::ptr_eq(k, x)).map(|(_, c)| c.clone())) {
1078	                return Ok((c, v.clone()));
1079	            }
1080	            let c: Rc<Vec<char>> = Rc::new(x.s.chars().collect());
1081	            LAST.with(|l| *l.borrow_mut() = Some((x.clone(), c.clone())));
1082	            Ok((c, v.clone()))
1083	        }
1084	        V::Ext(e) if matches!(e.native(), Some(Ok(V::Str(_)))) => re_str(&e.native().unwrap()?),
1085	        _ => type_err(format!("expected string or bytes-like object, got '{}'", tn(v))),
1086	    }
